    """16 kHz mono float32 through ffmpeg, for files the built-in decoder cannot read."""
    import numpy
    r = subprocess.run(["ffmpeg", "-v", "error", "-i", p, "-ac", "1", "-ar", "16000", "-f", "f32le", "-"],
